1: /* main.c
2:  * Command line interface.
3:  *
4:  * This fixed point version of shine is based on Gabriel Bouvigne's original
5:  * source, version 0.1.2
6:  * It was converted for use on Acorn computers running RISC OS and will require
7:  * the assembler multiply file to be replaced for other platforms.
8:  * 09/02/01 P.Everett
9:  *
10:  * Converted to a no-globals library-based system primarily for ARM-LINUX-GCC
11:  * but also works on x86 and x86_64 with the Makefile-generic, however
12:  * quality is worse right now on non-ARM as the noarch file uses bad math.
13:  * Jan 2, 2006 P.Roberts
14:  *
15:  */
16: 
17: /* Global headers. */
18: #include <stdio.h>
19: #include <stdlib.h>
20: #include <string.h>
21: #include <time.h>
22: 
23: /* Required headers from libshine. */
24: #include "layer3.h"
25: 
26: /* Local header */
27: #include "main.h"
28: #include "wave.h"
29: 
30: /* Some global vars. */
31: char *infname, *outfname;
32: FILE *infile, *outfile;
33: int quiet = 0;
34: int _verbose = 0;
35: int stereo = STEREO;
36: int force_mono = 0;
37: 
38: int verbose() { return _verbose; }
39: 
40: /* Write out the MP3 file */
41: int write_mp3(long bytes, void *buffer, void *config) {
42:   return fwrite(buffer, sizeof(unsigned char), bytes, outfile) /
43:          sizeof(unsigned char);
44: }
45: 
46: /* Output error message and exit */
47: void error(char *s) {
48:   fprintf(stderr, "Error: %s\n", s);
49:   exit(1);
50: }
51: 
52: static void print_name() { printf("shineenc (Liquidsoap version)\n"); }
53: 
54: static void print_usage() {
55:   printf("Usage: shineenc [options] <infile> <outfile>\n\n");
56:   printf("Use \"-\" for standard input or output.\n\n");
57:   printf("Options:\n");
58:   printf(" -h            this help message\n");
59:   printf(" -b <bitrate>  set the bitrate [8-320], default 128kbit\n");
60:   printf(" -m            force encoder to operate in mono\n");
61:   printf(" -c            set copyright flag, default off\n");
62:   printf(" -j            encode in joint stereo (stereo data only)\n");
63:   printf(" -d            encode in dual-channel (stereo data only)\n");
64:   printf(" -q            quiet mode\n");
65:   printf(" -v            verbose mode\n");
66: }
67: 
68: /* Use these default settings, can be overridden */
69: static void set_defaults(shine_config_t *config) {
70:   shine_set_config_mpeg_defaults(&config->mpeg);
71: }
72: 
73: /* Parse command line arguments */
74: static int parse_command(int argc, char **argv, shine_config_t *config) {
75:   int i = 0;
76: 
77:   if (argc < 3)
78:     return 0;
79: 
80:   while (argv[++i][0] == '-' && argv[i][1] != '\000' && argv[i][1] != ' ')
81:     switch (argv[i][1]) {
82:     case 'b':
83:       config->mpeg.bitr = atoi(argv[++i]);
84:       break;
85: 
86:     case 'm':
87:       force_mono = 1;
88:       break;
89: 
90:     case 'j':
91:       stereo = JOINT_STEREO;
92:       break;
93: 
94:     case 'd':
95:       stereo = DUAL_CHANNEL;
96:       break;
97: 
98:     case 'c':
99:       config->mpeg.copyright = 1;
