17: /* RISC OS specifics */
18: #define WAVE 0xfb1 /* Wave filetype */
19: #define DATA 0xffd /* Data filetype */
20: 
21: #define MODE_MONO 3
22: 
23: #ifdef SHINE_BIG_ENDIAN
24: #if defined(SHINE_HAVE_BSWAP_H)
25: #include <byteswap.h>
26: #elif defined(__GNUC__) &&                                                     \
27:     (__GNUC__ > 4 || (__GNUC__ == 4 && __GNUC_MINOR__ >= 2))
28: #define bswap_16(x) __builtin_bswap16(x)
29: #define bswap_32(x) __builtin_bswap32(x)
30: #else
31: #define bswap_16(x) ((((x) >> 8) & 0xff) | (((x)&0xff) << 8))
32: #define bswap_32(x)                                                            \
33:   ((((x)&0xFF) << 24) | (((x) >> 24) & 0xFF) | (((x)&0x0000FF00) << 8) |       \
34:    (((x)&0x00FF0000) >> 8))
35: #endif
36: #endif
