38: typedef struct {
39:   char id[4];
40:   uint32_t length;
41: } riff_chunk_header_t;
42: 
43: typedef struct {
44:   riff_chunk_header_t header;
45:   char wave[4];
46: } wave_chunk_t;
47: 
48: typedef struct {
49:   riff_chunk_header_t header;
50:   uint16_t format;      /* MS PCM = 1 */
51:   uint16_t channels;    /* channels, mono = 1, stereo = 2 */
52:   uint32_t sample_rate; /* samples per second = 44100 */
53:   uint32_t byte_rate;   /* bytes per second = samp_rate * byte_samp = 176400 */
54:   uint16_t frame_size;  /* block align (bytes per sample) = channels *
55:                            bits_per_sample / 8 = 4 */
56:   uint16_t depth;       /* bits per sample = 16 for MS PCM (format specific) */
57: } fmt_chunk_t;
58: 
59: #ifdef SHINE_BIG_ENDIAN
60: #define native_fmt_chunk(fmt)                                                  \
61:   {                                                                            \
62:     fmt.header.length = bswap_32(fmt.header.length);                           \
63:     fmt.format = bswap_16(fmt.format);                                         \
64:     fmt.channels = bswap_16(fmt.channels);                                     \
65:     fmt.sample_rate = bswap_32(fmt.sample_rate);                               \
66:     fmt.byte_rate = bswap_32(fmt.byte_rate);                                   \
67:     fmt.frame_size = bswap_16(fmt.frame_size);                                 \
68:     fmt.depth = bswap_16(fmt.depth);                                           \
69:   }
70: #endif
