72: void wave_seek(FILE *file, int has_seek, uint32_t bytes) {
73:   uint32_t i;
74:   if (has_seek == 1)
75:     fseek(file, bytes, SEEK_CUR);
76:   else {
77:     for (i = 0; i < bytes; i++)
78:       getc(file);
79:   }
80: }
