82: unsigned char wave_get_chunk_header(FILE *file, int has_seek, const char id[4],
83:                                     riff_chunk_header_t *header) {
84:   unsigned char found = 0;
85:   uint32_t chunk_length;
86: 
87:   if (verbose())
88:     fprintf(stderr, "Looking for chunk '%s'\n", id);
89: 
90:   while (!found) {
91:     if (fread(header, sizeof(riff_chunk_header_t), 1, file) != 1) {
92:       if (feof(file))
93:         return 0;
94:       else
95:         error("Read error");
96:     }
97: 
98:     /* chunks must be word-aligned, chunk data doesn't need to */
99:     chunk_length = header->length + header->length % 2;
100:     if (verbose()) {
101:       fprintf(stderr, "Found chunk '%.4s', length: %u\n", header->id,
102:               header->length);
103:     }
104: 
105:     if (strncmp(header->id, id, 4) == 0)
106:       return 1;
107: 
108:     wave_seek(file, has_seek, chunk_length);
109:   }
110: 
111:   return 1;
112: }
